<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#0f1720">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<link rel="manifest" href="manifest.webmanifest">
<link rel="icon" href="icons/icon-192.png">
<link rel="apple-touch-icon" href="icons/icon-192.png">
<title>Treino Híbrido — Juarez</title>
<style>
:root {
  --bg:#0f1720; --panel:#18232e; --panel2:#202e3a; --line:#314351;
  --text:#eef4f7; --muted:#a8b8c4; --accent:#65d39a; --accent2:#f0c86b;
  --danger:#ff7b7b; --blue:#7bb9ff; --shadow:0 12px 35px rgba(0,0,0,.24);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:linear-gradient(180deg,#0c131a,var(--bg));color:var(--text);font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;line-height:1.45}
a{color:var(--blue)}
button,input,select,textarea{font:inherit}
button{cursor:pointer}
.app{max-width:1120px;margin:auto;padding:16px 16px 90px}
.hero{background:linear-gradient(135deg,#1c2e32,#18232e 60%,#242d31);border:1px solid var(--line);border-radius:22px;padding:20px;box-shadow:var(--shadow)}
.hero h1{margin:0 0 6px;font-size:clamp(1.6rem,5vw,2.5rem)}
.hero p{margin:.35rem 0;color:var(--muted)}
.badges{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
.badge{border:1px solid var(--line);background:#14202a;border-radius:999px;padding:7px 10px;font-size:.86rem}
.nav{position:sticky;top:0;z-index:20;display:flex;gap:8px;overflow:auto;padding:12px 0;background:linear-gradient(180deg,var(--bg) 70%,transparent)}
.nav button{white-space:nowrap;border:1px solid var(--line);background:var(--panel);color:var(--text);padding:9px 12px;border-radius:12px}
.nav button.active{background:var(--accent);color:#082017;border-color:transparent;font-weight:700}
.section{display:none}
.section.active{display:block}
.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}
.card{grid-column:span 12;background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:16px;box-shadow:var(--shadow)}
.card h2,.card h3{margin-top:0}
.metric-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.metric{background:var(--panel2);border:1px solid var(--line);border-radius:14px;padding:12px}
.metric b{font-size:1.3rem;display:block}
.muted{color:var(--muted)}
.day-card{margin:12px 0}
.day-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}
.day-head h3{margin-bottom:3px}
.exercise{border-top:1px solid var(--line);padding:13px 0}
.exercise:first-of-type{border-top:0}
.exercise-top{display:flex;gap:10px;justify-content:space-between;align-items:flex-start}
.exercise-title{font-weight:750}
.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:3px 7px;font-size:.78rem;color:var(--muted);margin:3px 4px 0 0}
.video{text-decoration:none;background:#2a3945;border:1px solid var(--line);padding:7px 9px;border-radius:10px;white-space:nowrap}
.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
label{display:block;font-size:.86rem;color:var(--muted)}
input,select,textarea{width:100%;margin-top:5px;border:1px solid var(--line);background:#101a22;color:var(--text);border-radius:10px;padding:10px}
textarea{min-height:90px;resize:vertical}
.btn{border:0;border-radius:12px;padding:11px 14px;font-weight:750;background:var(--accent);color:#092018}
.btn.secondary{background:#2a3945;color:var(--text);border:1px solid var(--line)}
.btn.warn{background:var(--accent2);color:#2a210b}
.btn.danger{background:#4a2529;color:#ffd7d7;border:1px solid #744148}

