function updateRestTimer() {
  if(!restEndAt) {
    document.getElementById("timerDisplay").textContent=restFinished?"PRONTO!":"Pronto";
    document.getElementById("restProgressBar").style.width=restFinished?"100%":"0%";
    return;
  }
  const remainingMs=restEndAt-Date.now();
  if(remainingMs<=0) { finishRestTimer(); return; }
  const remainingSeconds=Math.ceil(remainingMs/1000);
  document.getElementById("timerDisplay").textContent=formatRest(remainingSeconds);
  const elapsed=restTotalSeconds-remainingMs/1000;
  document.getElementById("restProgressBar").style.width=`${Math.max(0,Math.min(100,(elapsed/restTotalSeconds)*100))}%`;
}
function stopTimer(reset=true) {
  if(restTimerInterval) clearInterval(restTimerInterval);
  restTimerInterval=null; restEndAt=0; restTotalSeconds=0; restFinished=!reset; saveTimerState();
  document.getElementById("timerDisplay").textContent=reset?"Pronto":"PRONTO!";
  document.getElementById("restProgressBar").style.width=reset?"0%":"100%";
  if(reset) setTimerStatus("Descanso cancelado.");
}
function finishRestTimer() {
  if(restFinished) return;
  if(restTimerInterval) clearInterval(restTimerInterval);
  restTimerInterval=null; restEndAt=0; restFinished=true; saveTimerState();
  document.getElementById("timerDisplay").textContent="PRONTO!";
  document.getElementById("restProgressBar").style.width="100%";
  playFinishAlert(); setTimerStatus("Descanso concluído. Próxima série.");
}
function completeSet(button,restSeconds) {
  const row=button.closest("tr"); const done=row.classList.toggle("set-done");
  button.textContent=done?"↺":"✓"; button.title=done?"Desmarcar série":"Concluir série e iniciar descanso";
  if(done && document.getElementById("autoRestEnabled")?.checked && Number(restSeconds)>0) startTimer(restSeconds);
}
function ensureAudioContext() {
  try {
    if(!audioContext) audioContext=new (window.AudioContext||window.webkitAudioContext)();
    if(audioContext.state==="suspended") audioContext.resume();
    return true;
  } catch(e) { return false; }
}
function enableAlerts() {
  const ok=ensureAudioContext(); alertsEnabled=ok;
  const btn=document.getElementById("alertEnableBtn");
  if(btn) btn.textContent=ok?"Alertas ativados ✓":"Som indisponível";
  if(navigator.vibrate && document.getElementById("vibrationEnabled")?.checked) navigator.vibrate(80);
  if(ok) playBeepSequence(true);
  setTimerStatus(ok?"Som ativado. Faça o teste com os fones conectados.":"Este navegador não liberou o áudio.");
}
function playTone(at,frequency,duration,volume) {
  if(!audioContext) return;
  const osc=audioContext.createOscillator(), gain=audioContext.createGain();
  osc.type="sine"; osc.frequency.setValueAtTime(frequency,at);
  gain.gain.setValueAtTime(0.0001,at);
  gain.gain.exponentialRampToValueAtTime(volume,at+0.015);
  gain.gain.exponentialRampToValueAtTime(0.0001,at+duration);
  osc.connect(gain); gain.connect(audioContext.destination); osc.start(at); osc.stop(at+duration+0.03);
}
function playBeepSequence(test=false) {
  if(!ensureAudioContext()) return;
  const volume=Number(document.getElementById("alertVolume")?.value||0.25);
  const now=audioContext.currentTime+0.03;
  playTone(now,880,0.16,volume); playTone(now+0.24,1046,0.16,volume); playTone(now+0.48,1318,test?0.24:0.42,volume);
}
function playFinishAlert() {
  if(alertsEnabled||ensureAudioContext()) playBeepSequence(false);
  if(navigator.vibrate && document.getElementById("vibrationEnabled")?.checked) navigator.vibrate([250,120,250,120,650]);
}
function testAlerts() {
  alertsEnabled=ensureAudioContext(); playBeepSequence(true);
  if(navigator.vibrate && document.getElementById("vibrationEnabled")?.checked) navigator.vibrate([160,90,280]);
  setTimerStatus("Alerta de teste executado.");
}
function setTimerStatus(text) {
  const el=document.getElementById("timerStatus"); if(el) el.textContent=text;
}
function toggleTimerPanel() {
  const panel=document.getElementById("timerPanel"); panel.classList.toggle("collapsed");
  document.getElementById("timerCollapseBtn").textContent=panel.classList.contains("collapsed")?"+":"−";
}
async function toggleWakeLock() {
  const checkbox=document.getElementById("keepAwake");
  if(!checkbox?.checked) {
    if(wakeLockSentinel) { try { await wakeLockSentinel.release(); } catch(e) {} wakeLockSentinel=null; }
    setTimerStatus("Tela pode apagar normalmente."); return;
  }
  if(!("wakeLock" in navigator)||!window.isSecureContext) {
    checkbox.checked=false; setTimerStatus("Manter tela ligada funciona quando o app estiver publicado em HTTPS/PWA."); return;
  }
  try {
    wakeLockSentinel=await navigator.wakeLock.request("screen");
    wakeLockSentinel.addEventListener("release",()=>{wakeLockSentinel=null;});
    setTimerStatus("Tela será mantida ligada durante o treino.");
  } catch(e) { checkbox.checked=false; setTimerStatus("Não foi possível manter a tela ligada."); }
}
function initTimers() {
  loadTimerState(); updateWorkoutDisplay();
  if(workoutClock.running&&!workoutTicker) workoutTicker=setInterval(updateWorkoutDisplay,500);
  if(restEndAt>Date.now()) { updateRestTimer(); restTimerInterval=setInterval(updateRestTimer,200); }
  else if(restEndAt) finishRestTimer(); else updateRestTimer();
  document.addEventListener("visibilitychange",async()=>{
    updateWorkoutDisplay(); updateRestTimer();
    if(document.visibilityState==="visible"&&document.getElementById("keepAwake")?.checked&&!wakeLockSentinel) await toggleWakeLock();
  });
}

function markdownReport() {
  const p=state.profile;
  let md=`# Acompanhamento de treino — Juarez\n\n`;
  md+=`## Perfil e medidas atuais\n\n`;
  md+=`- Altura: ${p.height_cm} cm\n- Peso: ${p.weight_kg} kg\n- Cintura: ${p.waist_cm} cm\n- Peito: ${p.chest_cm} cm\n- Barra fixa: ${p.pullups} repetições\n- Prancha: ${p.plank_sec} segundos\n- Bicicleta: ${p.bike_daily_km} km/dia\n\n`;
  md+=`**Objetivo:** ${p.goal}\n\n`;
  md+=`## Plano semanal\n\n`;
  Object.entries(WORKOUTS).forEach(([k,w])=>{
    md+=`### ${w.label} — ${w.focus}\n\n`;
    w.exercises.forEach((e,i)=>{
      md+=`${i+1}. **${e.name}** — ${e.sets}×${e.reps}, descanso ${e.rest}s, RIR ${e.rir}. ${e.notes}\n`;
    });
    md+="\n";
  });
  md+=`## Histórico\n\n`;
  [...state.sessions].sort((a,b)=>a.date.localeCompare(b.date)).forEach(s=>{
    const w=WORKOUTS[s.dayKey];
    md+=`### ${fmtDate(s.date)} — ${w?w.label:s.dayKey}\n\n`;
    md+=`- Status: ${s.status}\n- Semáforo: ${s.readiness||"—"}\n- Sono: ${s.sleepHours||"—"}\n- Qualidade do sono: ${s.sleepQuality||"—"}/5\n- Energia: ${s.energy||"—"}/5\n- Dor: ${s.pain||"0"}/10\n- Duração do treino: ${s.durationSeconds?formatClock(s.durationSeconds):"—"}\n`;
    (s.exercises||[]).forEach(e=>{
      md+=`- **${e.name}:** ${e.sets.map(x=>`${x.weight||"—"} × ${x.reps||"—"}${x.rir?` (RIR ${x.rir})`:""}`).join(" | ")}\n`;
    });
    if(s.notes)md+=`- Observações: ${s.notes}\n`;
    md+="\n";
  });
  return md;
}
function downloadBlob(content, filename, type) {
  const blob=new Blob([content],{type});
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a");a.href=url;a.download=filename;a.click();
  setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function exportMarkdown() {
  downloadBlob(markdownReport(),`acompanhamento_treino_juarez_${new Date().toISOString().slice(0,10)}.md`,"text/markdown;charset=utf-8");
}

